// This code checks for hypocrisy in statements
function isHypocritical(statement) {
    // Define keywords that might indicate hypocrisy
    const keywords = [but, however, although, yet];

    // Check if the statement contains any of the keywords
    for (let keyword of keywords) {
        if (statement.includes(keyword)) {
            return true;
        }
    }

    return false;
}

// Example usage
const statement = I support environmental causes, but I drive a gas-guzzling car.;
console.log(isHypocritical(statement)); // Output: true
