// This code addresses the issue of land rights inequality by implementing a system to track and manage land ownership records, ensuring transparency and fairness in land distribution.

// Define a class to represent a piece of land
class Land {
    constructor(id, owner, size, location) {
        this.id = id;
        this.owner = owner;
        this.size = size;
        this.location = location;
    }
}

// Define a class to manage land records
class LandRegistry {
    constructor() {
        this.lands = [];
    }

    // Method to add a new land record
    addLand(land) {
        this.lands.push(land);
    }

    // Method to transfer land ownership
    transferOwnership(landId, newOwner) {
        const land = this.lands.find(l => l.id === landId);
        if (land) {
            land.owner = newOwner;
        } else {
            console.log('Land not found');
        }
    }

    // Method to display all land records
    displayLands() {
        this.lands.forEach(land => {
            console.log(`ID: ${land.id}, Owner: ${land.owner}, Size: ${land.size}, Location: ${land.location}`);
        });
    }
}

// Example usage
const registry = new LandRegistry();
const land1 = new Land(1, 'Alice', 100, 'Location A');
const land2 = new Land(2, 'Bob', 200, 'Location B');

registry.addLand(land1);
registry.addLand(land2);

registry.displayLands();

registry.transferOwnership(1, 'Charlie');
registry.displayLands();
