// This code snippet highlights the issue of hypocrisy in a given context.
// It checks for inconsistencies between stated beliefs and actions.

function checkHypocrisy(statements, actions) {
    let inconsistencies = [];

    statements.forEach((statement, index) => {
        if (statement !== actions[index]) {
            inconsistencies.push({
                statement: statement,
                action: actions[index]
            });
        }
    });

    return inconsistencies.length > 0 ? inconsistencies : No hypocrisy detected;
}

// Example usage:
let beliefs = [I care about the environment, I support local businesses];
let behaviors = [Uses plastic bags, Shops at big chains];

console.log(checkHypocrisy(beliefs, behaviors));
```

