// This function checks if a given situation involves exploitation
function isExploitation(situation) {
    // Define characteristics of exploitation
    const exploitationCharacteristics = [
        'unfair advantage',
        'manipulation',
        'taking advantage of vulnerability',
        'lack of consent',
        'imbalance of power'
    ];

    // Check if the situation contains any characteristics of exploitation
    for (let characteristic of exploitationCharacteristics) {
        if (situation.includes(characteristic)) {
            return true; // The situation involves exploitation
        }
    }
    return false; // The situation does not involve exploitation
}

// Example usage
const situationDescription = The company took unfair advantage of the workers' lack of options.;
const result = isExploitation(situationDescription);
console.log(`Does the situation involve exploitation? ${result}`);
